parameters.query:
SELECT id, shared_slugs, next_index, last_posted_slug, last_posted_at
FROM linkedin_rotation
WHERE id = 1;

parameters.jsCode:
const rot = $input.first().json;
const feed = $('Resolve Feed').first().json;

let sharedSlugs = rot.shared_slugs;
if (typeof sharedSlugs === 'string') {
  sharedSlugs = JSON.parse(sharedSlugs);
}
if (!Array.isArray(sharedSlugs)) sharedSlugs = [];

let cursor = Number(rot.next_index);
if (!Number.isFinite(cursor)) cursor = 0;

const posts = Array.isArray(feed.posts) ? feed.posts : [];
if (!posts.length) {
  throw new Error('linkedin-posts.json returned no posts');
}

const sortedPosts = [...posts].sort((a, b) => {
  const aKey = String(a.datePublished ?? a.publishedAt ?? a.date ?? a.slug ?? '');
  const bKey = String(b.datePublished ?? b.publishedAt ?? b.date ?? b.slug ?? '');
  const byDate = aKey.localeCompare(bKey);
  if (byDate !== 0) return byDate;
  return String(a.slug ?? '').localeCompare(String(b.slug ?? ''));
});

const totalPosts = sortedPosts.length;
const sharedSet = new Set(sharedSlugs);
cursor = ((cursor % totalPosts) + totalPosts) % totalPosts;

