parameters.jsCode:
// Emits the post feed regardless of whether it came from the live blog or the
// Postgres cache, so a blog outage can no longer skip an hourly slot.
const row = $input.first()?.json ?? {};

let feed = row.feed;
if (typeof feed === 'string') {
  try { feed = JSON.parse(feed); } catch (err) { feed = null; }
}

const posts = feed && Array.isArray(feed.posts) ? feed.posts : [];
if (!posts.length) {
  throw new Error(
    'No usable feed: the live fetch failed and linkedin_feed_cache is empty or invalid. ' +
    'Check https://blog.michaelsam94.com/linkedin-posts.json and SELECT * FROM linkedin_feed_cache.'
  );
}

const fetchedAt = row.fetched_at ? new Date(row.fetched_at) : null;
const ageHours = fetchedAt
  ? Math.round(((Date.now() - fetchedAt.getTime()) / 3600000) * 10) / 10
  : null;

return [{
  json: {
    ...feed,
    feedSource: row.feed_source ?? 'unknown',
    cacheFetchedAt: row.fetched_at ?? null,
    cacheAgeHours: ageHours,
  },
}];
